const pick = (row, names) => {
  const keys = Object.keys(row);
  for (const n of names) {
    const k = keys.find(k => k.trim().toLowerCase() === n);
    if (k) return row[k];
  }
  return '';
};
const pad = n => String(n).padStart(2, '0');
function normDate(v) {
  if (v === null || v === undefined || v === '') return '';
  if (typeof v === 'number' && v > 20000 && v < 80000) { // serial Excel/Sheets
    const d = new Date(Math.round((v - 25569) * 86400 * 1000));
    return d.getUTCFullYear() + '-' + pad(d.getUTCMonth() + 1) + '-' + pad(d.getUTCDate());
  }
  const s = String(v).trim().split(/[ T]/)[0];
  let m;
  if ((m = s.match(/^(\d{4})[-\/.](\d{1,2})[-\/.](\d{1,2})$/))) return m[1] + '-' + pad(m[2]) + '-' + pad(m[3]);
  if ((m = s.match(/^(\d{1,2})[-\/.](\d{1,2})[-\/.](\d{4})$/))) return m[3] + '-' + pad(m[2]) + '-' + pad(m[1]); // DD/MM/YYYY
  const d = new Date(String(v));
  if (!isNaN(d)) return d.getFullYear() + '-' + pad(d.getMonth() + 1) + '-' + pad(d.getDate());
  return '';
}
function normNominal(v) {
  if (v === null || v === undefined) return '';
  let s = String(v).trim();
  s = s.replace(/[,.]\d{1,2}$/, (x) => /^[,.]\d{2}$/.test(x) ? '' : x); // buang desimal ,00 / .00
  return s.replace(/[^0-9]/g, ''); // hapus karakter non-numerik
}

return $input.all().map((it, i) => {
  const r = it.json;
  const tanggal = normDate(pick(r, ["tanggal","date","tgl"]));
  const nominal = normNominal(pick(r, ["nominal","amount","jumlah"]));
  return { json: {
    source: 'Internal',
    row_no: i + 1,
    id: pick(r, ["id","id_transaksi","no"]),
    tanggal,
    nominal,
    deskripsi: pick(r, ["deskripsi","keterangan","description"]),
    match_key: tanggal + '_' + nominal
  }};
});

