return $input.all().map((it, i) => {
  const r = it.json;
  const tanggal = normDate(pick(r, ["tanggal","date","tgl"]));
  const nominal = normNominal(pick(r, ["nominal","amount","jumlah","kredit","debit"]));
  return { json: {
    source: 'Bank',
    row_no: i + 1,
    id: pick(r, ["id","ref","no_referensi"]),
