const internal = $('Clean Internal').all().map(i => i.json);
const bank = $('Clean Bank').all().map(i => i.json);

// index bank per match_key (mendukung transaksi duplikat)
const bankMap = {};
bank.forEach(b => { (bankMap[b.match_key] = bankMap[b.match_key] || []).push(b); });

const matched = [], missingInBank = [];
internal.forEach(t => {
  const list = bankMap[t.match_key];
  if (list && list.length) { list.shift(); matched.push({ ...t, status: 'Matched' }); }
  else missingInBank.push({ ...t, status: 'Missing in Bank' });
});
const unrecorded = [];
Object.values(bankMap).forEach(l => l.forEach(b => unrecorded.push({ ...b, status: 'Unrecorded Internal' })));

const rp = n => 'Rp ' + Number(n || 0).toLocaleString('id-ID');
const line = x => '- ' + x.tanggal + ' | ' + rp(x.nominal) + ' | ' + (x.deskripsi || x.id || '-');
const issues = missingInBank.length + unrecorded.length;

let msg = 'LAPORAN REKONSILIASI\n';
msg += 'Internal: ' + internal.length + ' | Bank: ' + bank.length + ' | Matched: ' + matched.length + '\n\n';
if (missingInBank.length) msg += 'MISSING IN BANK (ada di Internal, tidak ada di Bank): ' + missingInBank.length + '\n' + missingInBank.map(line).join('\n') + '\n\n';
if (unrecorded.length) msg += 'UNRECORDED INTERNAL (ada di Bank, tidak ada di Internal): ' + unrecorded.length + '\n' + unrecorded.map(line).join('\n');

return [{ json: {
  has_issue: issues > 0,
  total_internal: internal.length,
  total_bank: bank.length,
  matched_count: matched.length,
  missing_in_bank_count: missingInBank.length,
  unrecorded_internal_count: unrecorded.length,
  message: msg.trim(),
  matched, missing_in_bank: missingInBank, unrecorded_internal: unrecorded
}}];
